double newton_raphson(double (*f)(double), double (*df)(double), double x0, double tol, int max_iter) {
    double x = x0;
    for (int i = 0; i < max_iter; i++) {
        double fx = f(x), dfx = df(x);
        if (fabs(dfx) < 1e-12) break;
        double dx = fx / dfx;
        x -= dx;
        if (fabs(dx) < tol) break;
    }
    return x;
}

