double rk4_step(double (*f)(double, double), double t, double y, double h) {
    double k1 = h * f(t, y);
    double k2 = h * f(t + 0.5 * h, y + 0.5 * k1);
    double k3 = h * f(t + 0.5 * h, y + 0.5 * k2);
    double k4 = h * f(t + h, y + k3);
    return y + (k1 + 2 * k2 + 2 * k3 + k4) / 6.0;
}

